description?: string;
/** Error reference code shown in small print. */
digest?: string;
onRetry?: () => void;
/** Retry button label. Defaults to "Reintentar". */
retryLabel?: string;
/** Secondary link target (e.g. home). */
secondaryHref?: string;
secondaryLabel?: string;
/** Lucide icon for the secondary link. */
secondaryIcon?: React.ComponentType<{ className?: string }>;

dtsPropsFor.SubmitButton:
children: React.ReactNode;
/** Label shown while the enclosing form's action is pending. Defaults to "Guardando…". */
pendingLabel?: string;
className?: string;
variant?: 'default' | 'destructive' | 'outline' | 'secondary' | 'ghost' | 'link';
size?: 'default' | 'sm' | 'lg' | 'icon';

dtsPropsFor.ConfirmDialog:
open: boolean;
onOpenChange: (open: boolean) => void;
title: string;
description?: React.ReactNode;
/** Extra fields rendered between the description and the footer. */
children?: React.ReactNode;
confirmLabel?: string;
cancelLabel?: string;
/** `destructive` makes the confirm button red. */
variant?: 'default' | 'destructive';
/** Type-to-confirm: confirm stays disabled until this exact phrase is typed. */
